// ═══════════════════════════════════════════════════════════════════════
// ║ Brand typefaces, embedded (latin subset, SIL Open Font License, from the
// ║ @fontsource packages): Cinzel Decorative 700 and Cinzel 700/900 for the
// ║ Ringed Z wordmark and button lettering, Marcellus SC for the story line.
// ║ Embedded so the title screen, the Lab and the home page never fall back.
// ═══════════════════════════════════════════════════════════════════════
(function(){ if(typeof document==='undefined')return; var st=document.createElement('style'); st.textContent="@font-face{font-family:'Cinzel Decorative';font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Cinzel';font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Cinzel';font-weight:900;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Marcellus SC';font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}"; document.head.appendChild(st);
  window.ZBrandFonts={list:[["Cinzel Decorative", "700"], ["Cinzel", "700"], ["Cinzel", "900"], ["Marcellus SC", "400"]], ready:false, load:function(){ if(!document.fonts||!document.fonts.load){ ZBrandFonts.ready=true; return Promise.resolve(); } return Promise.all(ZBrandFonts.list.map(function(f){ return document.fonts.load(f[1]+' 40px "'+f[0]+'"').catch(function(){}); })).then(function(){ ZBrandFonts.ready=true; if(typeof ZBrand!=='undefined')Object.keys(ZBrand.cache).forEach(function(k){ if(k.indexOf('w_')===0||k.indexOf('h2_')===0)delete ZBrand.cache[k]; }); }); }};
  ZBrandFonts.load(); })();
